import{_ as a,o as s,c as o,ae as n}from"./chunks/framework.CsNvqnj7.js";const m=JSON.parse('{"title":"La Forma Escrita En Memoria","description":"","frontmatter":{},"headers":[],"relativePath":"es/La Forma Escrita En Memoria.md","filePath":"es/La Forma Escrita En Memoria.md"}'),t={name:"es/La Forma Escrita En Memoria.md"};function r(i,e,l,d,p,c){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="la-forma-escrita-en-memoria" tabindex="-1">La Forma Escrita En Memoria <a class="header-anchor" href="#la-forma-escrita-en-memoria" aria-label="Permalink to &quot;La Forma Escrita En Memoria&quot;">​</a></h1><p>Si escribes en <code>.me</code> algo como:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jabellae.netget.port[80].request[]</span></span>
<span class="line"><span>|request[]| &lt;= 128</span></span>
<span class="line"><span>slot(n) = n mod 128</span></span>
<span class="line"><span>order = timestamp</span></span></code></pre></div><p>y luego te vas, eso no desaparece como &quot;config temporal&quot;. Queda como memoria semántica del kernel: en <code>memories</code>, en el <code>index</code>, exportable por snapshot, rehidratable después. Igual que hoy quedan dominios, secretos, derivaciones, identidad, etc.</p><p>Pero hay dos niveles.</p><h2 id="_1-queda-la-declaracion" tabindex="-1">1. Queda la declaración <a class="header-anchor" href="#_1-queda-la-declaracion" aria-label="Permalink to &quot;1. Queda la declaración&quot;">​</a></h2><p>Eso sí queda hoy, aunque todavía sea solo descripción:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>este espacio plural existe</span></span>
<span class="line"><span>su cardinalidad declarada es 128</span></span>
<span class="line"><span>su lógica declarada es seq mod 128</span></span>
<span class="line"><span>su orden es timestamp</span></span></code></pre></div><p>Otro runtime puede leerlo después y entender: &quot;ah, este nodo no es una lista cualquiera; es un plural con forma de ring&quot;.</p><h2 id="_2-queda-o-no-queda-el-enforcement" tabindex="-1">2. Queda o no queda el enforcement <a class="header-anchor" href="#_2-queda-o-no-queda-el-enforcement" aria-label="Permalink to &quot;2. Queda o no queda el enforcement&quot;">​</a></h2><p>Eso depende de si el kernel ya implementa pluralidad gobernada.</p><p>Hoy, si no hay enforcement nativo, la regla queda como conocimiento. El runtime que vuelva a levantar netget tendría que leer esa forma y obedecerla.</p><p>En el diseño futuro, cuando <code>[]</code> sea kernel-governed, entonces queda mucho más fuerte:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>la regla vive en .me</span></span>
<span class="line"><span>el kernel la rehidrata</span></span>
<span class="line"><span>cuando vuelven requests, el kernel sigue aplicando la misma regla</span></span></code></pre></div><p>O sea: te vas, vuelve el proceso, carga snapshot/memories, y <code>.me</code> recuerda no solo los datos, sino <strong>la forma del espacio</strong>.</p><p>Eso es lo bonito.</p><p>No queda &quot;código JS corriendo&quot; como un daemon eterno. Queda una <strong>forma declarada</strong> que el kernel sabe interpretar.</p><h2 id="el-mismo-patron-que-ya-existe-con" tabindex="-1">El mismo patrón que ya existe con <code>=</code> <a class="header-anchor" href="#el-mismo-patron-que-ya-existe-con" aria-label="Permalink to &quot;El mismo patrón que ya existe con \`=\`&quot;">​</a></h2><p>Es parecido a una derivación <code>=</code> hoy:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>total = price * quantity</span></span></code></pre></div><p>Tú te vas, pero la derivación queda. Cuando cambian <code>price</code> o <code>quantity</code>, <code>.me</code> sabe recomputar porque la relación vive en memoria.</p><p>La idea sería que con pluralidad pase igual:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request[] has cardinality 128</span></span>
<span class="line"><span>request[n] maps to n mod 128</span></span></code></pre></div><p>Tú te vas. La forma queda. El kernel despierta después. Carga memorias. Sigue sabiendo cómo gobernar <code>request[]</code>.</p><h2 id="respuesta-corta" tabindex="-1">Respuesta corta <a class="header-anchor" href="#respuesta-corta" aria-label="Permalink to &quot;Respuesta corta&quot;">​</a></h2><blockquote><p>Queda una memoria ejecutable de forma, no solo un dato.</p></blockquote><p>Hoy todavía sería memoria <strong>descriptiva</strong>. Con kernel-governed plurality sería memoria <strong>activa</strong>.</p><hr><h2 id="ver-tambien" tabindex="-1">Ver también <a class="header-anchor" href="#ver-tambien" aria-label="Permalink to &quot;Ver también&quot;">​</a></h2><ul><li><a href="./../Plurality-Is-Grammar.html">Plurality Is Grammar</a> — por qué <code>[]</code> es gramática (la forma plural), no un tipo de dato; esta nota aplica esa idea a la dimensión de memoria/persistencia, no solo de sintaxis.</li><li><a href="./../Algebra-of-Contexts.html">Algebra of Contexts</a> — el modelo de espacios sobre el que <code>request[]</code> vive.</li></ul>`,30)])])}const h=a(t,[["render",r]]);export{m as __pageData,h as default};
